{
  "title":"Lựa chọn chu trình làm lạnh dưới ràng buộc thời gian và năng lượng",
  "category":"categories.science",
  "plans":[
    {
      "id":"P9",
      "type":"multiple_choice",
      "recordIds":["F1"],
      "intent":"Xác định cặp số chu trình (n_A, n_B) nguyên hoặc thập phân cho phép đáp ứng tải nhiệt 2160 kJ đồng thời không vượt quá thời gian tối đa 200 giây và ngân sách điện 800 kJ; yêu cầu suy ra biên giới khả thi từ các bất đẳng thức thời gian và năng lượng rồi quyết định trường hợp nào thỏa mãn.",
      "reasoningSteps":["Suy ra biên giới khả thi bằng cách viết bất đẳng thức 60 s·n_A+40 s·n_B≤200 s và 180 kJ·n_A+240 kJ·n_B≤800 kJ","Kiểm tra từng lựa chọn đề xuất xem có thỏa mãn cả ba bất đẳng thức (thời gian, năng lượng, nhiệt) không và chọn đáp án đúng"]
    },
    {
      "id":"P10",
      "type":"selection",
      "recordIds":["F1"],
      "intent":"Kết hợp công thức COP=Q_c/W và các ràng buộc thời gian‑năng lượng để suy ra hệ số COP tổng thể của một hỗn hợp chu trình A và B; yêu cầu chọn tất cả các phát biểu đúng về hệ số COP tổng hợp và ảnh hưởng của việc tăng tỉ lệ chu trình B.",
      "reasoningSteps":["Tính COP riêng cho A (540/180=3) và B (600/240=2.5)","Sử dụng quan hệ Q_total=540 n_A+600 n_B và W_total=180 n_A+240 n_B để suy ra COP_hỗn_hợp=Q_total/W_total và đánh giá ảnh hưởng của tỉ lệ n_B/n_A"]
    },
    {
      "id":"P11",
      "type":"short_answer",
      "recordIds":["F1"],
      "intent":"Giả sử thời gian hoạt động đạt đúng 200 giây, suy ra giới hạn tối đa của n_A và n_B từ bất đẳng thức thời gian, sau đó kết hợp với giới hạn ngân sách điện 800 kJ để tính lượng nhiệt tối đa có thể lấy được mà không vi phạm bất kỳ ràng buộc nào.",
      "reasoningSteps":["Biểu diễn n_B=(200‑60 n_A)/40 từ ràng buộc thời gian","Thay thế n_B vào bất đẳng thức năng lượng 180 n_A+240 n_B≤800 để xác định miền khả thi của n_A, rồi tính Q_max=540 n_A+600 n_B tại điểm biên"]
    },
    {
      "id":"P12",
      "type":"multiple_choice",
      "recordIds":["F1"],
      "intent":"Xác định liệu việc chỉ sử dụng chế độ B (n_A=0) có thể đáp ứng tải nhiệt 2160 kJ mà không vượt quá thời gian 200 giây và ngân sách điện 800 kJ; yêu cầu suy ra kết quả bằng cách kết hợp các bất đẳng thức thời gian, năng lượng và nhiệt.",
      "reasoningSteps":["Áp dụng n_A=0 vào bất đẳng thức thời gian 40 s·n_B≤200 s và năng lượng 240 kJ·n_B≤800 kJ để tìm n_B tối đa","Kiểm tra xem 600 kJ·n_B tối đa có ≥2160 kJ hay không và đưa ra kết luận"]
    }
  ]
}
